import sys

def psi(n: int) -> int:
    s = str(n)
    res_digits = []
    for ch in s:
        res_digits.append(str(9 - int(ch)))
    res = int("".join(res_digits))
    return res

def weight(n: int) -> int:
    return n * psi(n)

def best_candidate(bound: int, is_upper: bool) -> int:
    s = str(bound)
    n = len(s)
    # candidate with first digit 4 or 5 and rest 9
    candidates = []
    for first in ['4', '5']:
        cand_str = first + '9' * (n - 1)
        cand = int(cand_str)
        if (is_upper and cand <= bound) or ((not is_upper) and cand >= bound):
            candidates.append(cand)
    if not candidates:
        # if none valid, just return bound
        return bound
    # choose the one closer to bound in direction
    if is_upper:
        return max(candidates)
    else:
        return min(candidates)

