    if not data:
        return
    l = int(data[0])
    r = int(data[1])

    # candidates to check
    cand = set()
    cand.add(l)
    cand.add(r)

    # around powers of 10 boundaries
    for k in range(1, 11):  # since r <= 1e9, 10^9 has 10 digits including 1e9
