    res_digits = []
    leading = True
    for ch in s:
        d = 9 - (ord(ch) - 48)
        if leading and d == 0:
            continue
        leading = False
        res_digits.append(str(d))
    if not res_digits:
        return 0
    return int(''.join(res_digits))

def weight(n: int) -> int:
    return n * reflection(n)

def best_in_range(l: int, r: int) -> int:
    # Candidate numbers are around powers of 10 boundaries
    candidates = set()

    # Always include boundaries
    candidates.add(l)
    candidates.add(r)

    # Generate powers of 10 within [1, 1e9]
    p = 1
    while p <= 10**9:
        # Consider p-1 and p if they are in range
        if l <= p <= r:
            candidates.add(p)
        if l <= p - 1 <= r and p - 1 >= 1:
            candidates.add(p - 1)
        p *= 10

    # Also consider numbers formed by leading digit 1 followed by 0..0
    # and their neighbors, as reflection tends to be large there.
    for k in range(1, 10):  # length of number
        val = 10 ** (k - 1)
        if l <= val <= r:
            candidates.add(val)
        if l <= val + 1 <= r:
            candidates.add(val + 1)
        if l <= val - 1 <= r and val - 1 >= 1:
            candidates.add(val - 1)

    max_w = 0
    for n in candidates:
        if l <= n <= r:
            w = weight(n)
            if w > max_w:
                max_w = w
    return max_w

